insert into public.stores (id, name, city, follower_count, contact_number, bio, story, external_shop_url, instagram, seller_type, banner_hex, avatar_hex)
values
('s_senja', 'Atelier Senja', 'Bandung', 12480, '6281221004411', 'Linen dan katun lokal, dijahit tangan di Dago.', 'Kami mulai dari satu mesin jahit di garasi rumah tahun 2019. Outfitly membantu kami bertemu pembeli yang peduli ukuran cm nyata, sehingga angka retur turun dan penjahit kami bisa fokus pada kualitas jahitan, bukan revisi ukuran.', 'https://shopee.co.id/', '@ateliersenja.bdg', 'umkm', '#C9B9A2', '#162D24'),
('s_kala', 'Kala Studio', 'Solo', 8930, '6281329007722', 'Lurik dan tenun Klaten untuk siluet kantor modern.', 'Ibu-ibu penenun di Pedan menenun lurik untuk kami setiap minggu. Kami membuka akun di Outfitly karena di sini pembeli menghargai cerita kain dan mau membaca tabel ukuran sebelum membeli.', 'https://www.tokopedia.com/', '@kalastudio.solo', 'umkm', '#A88A6A', '#7A5C46'),
('s_denim', 'Denim Lab', 'Pekalongan', 15720, '6285640003311', 'Selvedge denim 13,5 oz, potong dan cuci sendiri.', 'Kami percaya denim yang baik harus pas sejak hari pertama. Dengan Panduan Ukuran (cm) Outfitly, pelanggan tahu persis kelonggaran pinggang sebelum checkout. Itu alasan kami bergabung.', 'https://shopee.co.id/', '@denimlab.pkl', 'umkm', '#3D4F66', '#2A3A4F'),
('s_rengganis', 'Batik Rengganis', 'Pekalongan', 6210, '6285742008899', 'Batik cap dan tulis pewarna alam, potongan kontemporer.', 'Generasi ketiga pembatik di Kauman. Kami ingin batik dipakai ke kampus dan ke kantor, bukan hanya ke kondangan. Outfitly memberi ruang bagi kami untuk menunjukkan cara memadukannya.', 'https://www.tokopedia.com/', '@batikrengganis', 'umkm', '#8A5A3C', '#5B3A26'),
('s_sulam', 'Sulam Tasik', 'Tasikmalaya', 4980, '6282118006655', 'Bordir Kawalu dan hijab voal premium.', 'Bordir Tasik dikerjakan per helai oleh pengrajin di Kawalu. Kami bergabung dengan Outfitly supaya karya mereka sampai ke lemari anak muda di seluruh Indonesia.', 'https://shopee.co.id/', '@sulamtasik', 'umkm', '#D9C7C0', '#E58B94'),
('s_lawas', 'Lawas Yogya', 'Yogya', 9340, '6287738001122', 'Preloved terverifikasi, dicuci dan diukur ulang manual.', 'Setiap barang kami ukur ulang dalam posisi flat-lay dan kami foto kondisinya apa adanya. Satu barang, satu pemilik baru. Di Outfitly kami bisa mencantumkan cm nyata sehingga pembeli thrift tidak lagi menebak.', 'https://shopee.co.id/', '@lawas.yogya', 'community_preloved', '#B7A68A', '#4E5B3F'),
('s_rupa', 'Rupa Kembali', 'Bandung', 7120, '6281394005566', 'Collab Mitra: kurasi preloved bersama stylist Outfitly.', 'Kami adalah thrift shop mitra yang dikurasi langsung bersama tim stylist Outfitly. Setiap koleksi dipilih per musim agar mudah dipadukan dengan brand UMKM lain.', 'https://www.tokopedia.com/', '@rupakembali', 'collab_mitra', '#A3B9AD', '#153329'),
('s_langkah', 'Langkah Kriya', 'Yogya', 5560, '6281578002244', 'Sepatu dan tas kulit nabati, jahitan tangan.', 'Kulit kami disamak nabati di Magetan dan dijahit di bengkel kecil di Kotagede. Kami mencantumkan panjang insole cm di setiap produk karena kami ingin sepatu pertama Anda langsung pas.', 'https://shopee.co.id/', '@langkahkriya', 'umkm', '#6B4A35', '#3A2A1F'),
('s_kawung', 'Kawung Lasem', 'Lasem', 8420, '6285290011223', 'Batik tulis Lasem tiga negeri, dipotong jadi kemeja dan outer harian.', 'Kami bekerja dengan empat rumah batik tua di Karangturi. Lewat Outfitly, pembeli bisa melihat ukuran cm setiap potong sebelum memesan, jadi kain tulis yang mahal tidak salah ukuran.', 'https://www.tokopedia.com/', '@kawunglasem', 'umkm', '#9C3D2E', '#5E2219'),
('s_samak', 'Samak Garut', 'Garut', 11230, '6282214455667', 'Jaket dan sepatu kulit domba dari Sukaregang.', 'Bengkel kami ada di sentra penyamakan Sukaregang sejak 1998. Kami mencantumkan lebar bahu dan panjang insole di setiap produk karena kulit tidak bisa dikecilkan setelah dijahit.', 'https://shopee.co.id/', '@samakgarut', 'umkm', '#5A3B28', '#2E1D13'),
('s_endek', 'Tenun Pagi', 'Denpasar', 6780, '6281338877001', 'Endek Bali ATBM untuk atasan, rok, dan outer resort.', 'Penenun kami di Klungkung bekerja pagi hari sebelum panas. Nama toko kami dari situ. Outfitly membantu kami menjual ke luar Bali tanpa harus menebak ukuran pembeli.', 'https://www.tokopedia.com/', '@tenunpagi.bali', 'umkm', '#2F6F73', '#18413F'),
('s_sengkang', 'Sutra Sengkang', 'Makassar', 5310, '6281245566778', 'Sutra Wajo tenun tangan: blouse, outer, dan selendang.', 'Ibu kami menenun sutra di Sengkang. Kami membawanya ke potongan modern supaya bisa dipakai ke kantor dan kondangan di kota mana pun.', 'https://shopee.co.id/', '@sutrasengkang', 'umkm', '#B4495A', '#6E2333'),
('s_kotatua', 'Kota Tua Thrift', 'Jakarta', 18900, '6281288990011', 'Preloved streetwear dan workwear, sudah dicuci dan diukur ulang.', 'Kami mulai dari lapak di Pasar Senen. Sekarang setiap barang difoto apa adanya dan diukur flat-lay. Satu barang, satu pembeli.', 'https://shopee.co.id/', '@kotatuathrift', 'community_preloved', '#4A4A46', '#1F1F1D'),
('s_arek', 'Arek Workwear', 'Surabaya', 9650, '6281330044556', 'Kemeja kerja, chino, dan celana bahan pria yang tahan seharian.', 'Kami membuat pakaian kerja untuk anak muda Surabaya yang harus rapi dari pagi sampai malam. Ukuran kami diuji pada 40 orang sebelum diproduksi.', 'https://www.tokopedia.com/', '@arekworkwear', 'umkm', '#3E4B5C', '#1E2733'),
('s_apel', 'Apel Knitwear', 'Malang', 7340, '6285655667788', 'Rajutan katun dan akrilik untuk udara sejuk Malang.', 'Mesin rajut kami ada di Batu. Kami menulis berapa cm rajutan akan melar setelah dipakai, karena itu pertanyaan yang paling sering datang.', 'https://shopee.co.id/', '@apelknit', 'umkm', '#C8A98A', '#7A4F35'),
('s_voal', 'Rumah Voal', 'Bandung', 21400, '6281322113344', 'Hijab voal, pashmina, dan gamis harian.', 'Kami menjahit sendiri setiap hijab di Cigondewah. Ukuran dan jenis bahan selalu kami tulis, supaya tidak ada lagi hijab yang ternyata menerawang.', 'https://shopee.co.id/', '@rumahvoal', 'umkm', '#D8C3B4', '#8E6A5A'),
('s_senen', 'Arsip Senen', 'Jakarta', 6120, '6287788112233', 'Preloved formal: blazer, celana bahan, dan dress kantor.', 'Banyak blazer bagus berakhir di gudang. Kami memilih yang jahitannya masih kuat, membersihkannya, lalu mencantumkan ukuran bahu dan dada yang sebenarnya.', 'https://www.tokopedia.com/', '@arsipsenen', 'community_preloved', '#6C6255', '#2F2A24'),
('s_lemari', 'Lemari Bersama', 'Surabaya', 4870, '6281234009988', 'Collab Mitra: kurasi preloved musiman bersama stylist Outfitly.', 'Setiap bulan kami memilih 30 potong preloved yang mudah dipadukan dengan brand UMKM di Outfitly, lalu menyusunnya per tema.', 'https://shopee.co.id/', '@lemaribersama.sby', 'collab_mitra', '#9DB3A6', '#2C4A3E'),
('s_kanvas', 'Jejak Kanvas', 'Bandung', 13750, '6281221998877', 'Sneaker kanvas vulkanisir buatan Cibaduyut.', 'Kami melanjutkan bengkel sepatu kakek di Cibaduyut, tapi dengan sol vulkanisir dan kanvas tebal. Panjang insole tertulis di setiap ukuran.', 'https://www.tokopedia.com/', '@jejakkanvas', 'umkm', '#B9B4A6', '#3B3A35'),
('s_anyam', 'Anyam Nusa', 'Tasikmalaya', 5980, '6285223344551', 'Tas anyaman pandan, mendong, dan rotan dari Rajapolah.', 'Pengrajin anyaman di Rajapolah sudah menganyam turun-temurun. Kami membantu mendesain bentuk tas yang masuk akal untuk kampus dan kantor.', 'https://shopee.co.id/', '@anyamnusa', 'umkm', '#C9A86B', '#6B5326')
