('p01', 's_senja', 'Kemeja Linen Oversize Sage', 'Kemeja linen ramie dengan bahu jatuh dan kancing batok kelapa. Ringan untuk iklim tropis, makin lembut setelah dicuci.', 'top', 'minimalist', 'Hijau', array['#8EA89D', '#6F8A7E']::text[], 289000, null, 'new', false, 18, true, '[{"sizeLabel":"S","chestBustCm":104,"shoulderWidthCm":46,"garmentLengthCm":72},{"sizeLabel":"M","chestBustCm":108,"shoulderWidthCm":47,"garmentLengthCm":73},{"sizeLabel":"L","chestBustCm":112,"shoulderWidthCm":48,"garmentLengthCm":74},{"sizeLabel":"XL","chestBustCm":116,"shoulderWidthCm":49,"garmentLengthCm":75}]'::jsonb, 'https://images.unsplash.com/photo-1752047763318-901b21a622c5?auto=format&fit=crop&w=720&h=900&q=80#art:shirt:plain', 'Linen ramie 100%', false, 842, 311, array['kantor', 'kuliah', 'linen']::text[], '2026-11-17T09:00:00.000Z'),
('p02', 's_senja', 'Blouse Katun Krem Kerah Shanghai', 'Blouse katun voile dengan kerah shanghai rendah dan lengan 3/4. Siluet lurus yang aman untuk tubuh rectangle dan hourglass.', 'top', 'etnik_modern', 'Krem', array['#E8DCC4', '#CDBE9F']::text[], 239000, null, 'new', false, 24, true, '[{"sizeLabel":"S","chestBustCm":92,"shoulderWidthCm":37,"garmentLengthCm":64},{"sizeLabel":"M","chestBustCm":96,"shoulderWidthCm":38,"garmentLengthCm":65},{"sizeLabel":"L","chestBustCm":100,"shoulderWidthCm":39,"garmentLengthCm":66},{"sizeLabel":"XL","chestBustCm":104,"shoulderWidthCm":40,"garmentLengthCm":67}]'::jsonb, 'https://images.unsplash.com/photo-1745381251702-67b07225e516?auto=format&fit=crop&w=720&h=900&q=80#art:blouse:plain', 'Katun voile', false, 615, 204, array['kantor', 'kondangan']::text[], '2026-11-14T09:00:00.000Z'),
('p03', 's_kala', 'Outer Kimono Tenun Motif Bata', 'Outer kimono dari tenun ATBM Pedan bermotif geometris warna bata. Potongan lurus dan terbuka memberi garis vertikal yang memanjangkan siluet.', 'outerwear', 'etnik_modern', 'Pink', array['#D99A8C', '#6B4A3A']::text[], 365000, null, 'new', false, 9, true, '[{"sizeLabel":"S","chestBustCm":108,"shoulderWidthCm":44,"garmentLengthCm":78},{"sizeLabel":"M","chestBustCm":112,"shoulderWidthCm":45,"garmentLengthCm":79},{"sizeLabel":"L","chestBustCm":116,"shoulderWidthCm":46,"garmentLengthCm":80},{"sizeLabel":"XL","chestBustCm":120,"shoulderWidthCm":47,"garmentLengthCm":81}]'::jsonb, 'https://images.unsplash.com/photo-1769703078470-3bbf68b3900a?auto=format&fit=crop&w=720&h=900&q=80#art:kimono:stripe', 'Lurik tenun ATBM', false, 1032, 487, array['kantor', 'weekend', 'tenun']::text[], '2026-11-18T09:00:00.000Z'),
('p04', 's_kala', 'Celana Kulot Tenun Hitam', 'Kulot high waist dengan pinggang karet belakang. Jatuh lurus, nyaman untuk naik motor ke kampus.', 'pants', 'minimalist', 'Hitam', array['#2B2A28', '#4A4845']::text[], 259000, null, 'new', false, 20, true, '[{"sizeLabel":"27","waistCm":66,"hipsCm":100,"garmentLengthCm":92},{"sizeLabel":"28","waistCm":68.5,"hipsCm":102.5,"garmentLengthCm":92},{"sizeLabel":"30","waistCm":71,"hipsCm":105,"garmentLengthCm":93},{"sizeLabel":"32","waistCm":76,"hipsCm":110,"garmentLengthCm":94}]'::jsonb, 'https://images.unsplash.com/photo-1789110520755-058df30bf9cb?auto=format&fit=crop&w=720&h=900&q=80#art:culottes:plain', 'Tenun katun campur', true, 501, 166, array['kuliah', 'kantor']::text[], '2026-11-11T09:00:00.000Z'),
('p05', 's_denim', 'Straight Jeans Selvedge Indigo', 'Selvedge 13,5 oz non-stretch, potongan straight. Akan melar sekitar 1 cm di pinggang setelah dua minggu pemakaian.', 'jeans', 'streetwear', 'Biru', array['#2F4A6D', '#C7A15A']::text[], 449000, null, 'new', false, 14, true, '[{"sizeLabel":"27","waistCm":70,"hipsCm":96,"garmentLengthCm":100},{"sizeLabel":"28","waistCm":72.5,"hipsCm":98.5,"garmentLengthCm":100},{"sizeLabel":"30","waistCm":75,"hipsCm":101,"garmentLengthCm":101},{"sizeLabel":"32","waistCm":80,"hipsCm":106,"garmentLengthCm":102}]'::jsonb, 'https://images.unsplash.com/photo-1725387072845-7431bbc453bc?auto=format&fit=crop&w=720&h=900&q=80#art:jeans:denim', 'Denim selvedge 13,5 oz', false, 1488, 702, array['kasual', 'weekend', 'denim']::text[], '2026-11-19T09:00:00.000Z'),
('p06', 's_denim', 'Trucker Jacket Washed Blue', 'Jaket denim cuci batu dengan kancing tembaga. Lapisan pas untuk cuaca sejuk Bandung atau ruang kelas ber-AC.', 'outerwear', 'streetwear', 'Biru', array['#6E8BA8', '#C7A15A']::text[], 489000, null, 'new', false, 7, true, '[{"sizeLabel":"S","chestBustCm":100,"shoulderWidthCm":43,"garmentLengthCm":60},{"sizeLabel":"M","chestBustCm":104,"shoulderWidthCm":44,"garmentLengthCm":61},{"sizeLabel":"L","chestBustCm":108,"shoulderWidthCm":45,"garmentLengthCm":62},{"sizeLabel":"XL","chestBustCm":112,"shoulderWidthCm":46,"garmentLengthCm":63}]'::jsonb, 'https://images.unsplash.com/photo-1611312449408-fcece27cdbb7?auto=format&fit=crop&w=720&h=900&q=80#art:jacket:denim', 'Denim 12 oz', false, 977, 420, array['kasual', 'sejuk']::text[], '2026-11-15T09:00:00.000Z'),
('p07', 's_denim', 'Wide Leg Jeans Light Wash', 'Jeans wide leg cuci terang dengan kandungan 2% elastane. Pinggang tinggi menyeimbangkan bentuk tubuh pear.', 'jeans', 'casual', 'Biru', array['#A9C1D9', '#C7A15A']::text[], 419000, null, 'new', false, 11, true, '[{"sizeLabel":"27","waistCm":68,"hipsCm":98,"garmentLengthCm":102},{"sizeLabel":"28","waistCm":70.5,"hipsCm":100.5,"garmentLengthCm":102},{"sizeLabel":"30","waistCm":73,"hipsCm":103,"garmentLengthCm":103},{"sizeLabel":"32","waistCm":78,"hipsCm":108,"garmentLengthCm":104}]'::jsonb, 'https://images.unsplash.com/photo-1790283727726-f8ba027df653?auto=format&fit=crop&w=720&h=900&q=80#art:widejeans:denim', 'Denim katun 98%, elastane 2%', true, 734, 288, array['kuliah', 'weekend']::text[], '2026-11-16T09:00:00.000Z'),
('p08', 's_rengganis', 'Kemeja Batik Cap Sogan', 'Batik cap motif parang kecil dengan pewarna soga alam. Potongan regular, kerah kemeja modern.', 'top', 'etnik_modern', 'Coklat', array['#7A4E2D', '#E8C690']::text[], 325000, null, 'new', false, 16, true, '[{"sizeLabel":"S","chestBustCm":100,"shoulderWidthCm":44,"garmentLengthCm":70},{"sizeLabel":"M","chestBustCm":104,"shoulderWidthCm":45,"garmentLengthCm":71},{"sizeLabel":"L","chestBustCm":108,"shoulderWidthCm":46,"garmentLengthCm":72},{"sizeLabel":"XL","chestBustCm":112,"shoulderWidthCm":47,"garmentLengthCm":73}]'::jsonb, 'https://images.unsplash.com/photo-1760546659331-17903ed0d447?auto=format&fit=crop&w=720&h=900&q=80#art:shirt:batik', 'Katun primisima', false, 689, 251, array['kondangan', 'kantor', 'batik']::text[], '2026-11-13T09:00:00.000Z'),
('p09', 's_rengganis', 'Dress Batik Tulis Indigo Midi', 'Dress midi batik tulis pewarna indigo alam. Potongan A-line dengan tali pinggang, ideal untuk kondangan siang.', 'dress', 'etnik_modern', 'Biru', array['#2E3F5C', '#D9CBB0']::text[], 685000, null, 'new', false, 4, true, '[{"sizeLabel":"S","chestBustCm":88,"shoulderWidthCm":36,"garmentLengthCm":118},{"sizeLabel":"M","chestBustCm":92,"shoulderWidthCm":37,"garmentLengthCm":119},{"sizeLabel":"L","chestBustCm":96,"shoulderWidthCm":38,"garmentLengthCm":120},{"sizeLabel":"XL","chestBustCm":100,"shoulderWidthCm":39,"garmentLengthCm":121}]'::jsonb, 'https://images.unsplash.com/photo-1779501029074-3d48e7f6bbb9?auto=format&fit=crop&w=720&h=900&q=80#art:dress:batik', 'Katun prima, batik tulis', false, 1210, 655, array['kondangan', 'batik']::text[], '2026-11-18T09:00:00.000Z'),
('p10', 's_sulam', 'Hijab Voal Bordir Kawalu Dusty Pink', 'Hijab segi empat voal 115 x 115 cm dengan bordir tangan di satu sudut. Tidak licin dan mudah dibentuk.', 'hijab', 'minimalist', 'Pink', array['#E58B94', '#F3D3D6']::text[], 129000, null, 'new', false, 40, true, '[{"sizeLabel":"115 x 115","garmentLengthCm":115}]'::jsonb, 'https://images.unsplash.com/photo-1601869610370-907c3e63d7e0?auto=format&fit=crop&w=720&h=900&q=80#art:hijab:embroidery', 'Voal premium', false, 1532, 812, array['kuliah', 'kondangan']::text[], '2026-11-19T09:00:00.000Z'),
('p11', 's_sulam', 'Tunik Bordir Putih Gading', 'Tunik katun dengan bordir kerawang di bagian dada. Panjang menutup pinggul.', 'top', 'etnik_modern', 'Putih', array['#F4EFE3', '#D8CDB5']::text[], 345000, null, 'new', false, 8, true, '[{"sizeLabel":"S","chestBustCm":96,"shoulderWidthCm":38,"garmentLengthCm":86},{"sizeLabel":"M","chestBustCm":100,"shoulderWidthCm":39,"garmentLengthCm":87},{"sizeLabel":"L","chestBustCm":104,"shoulderWidthCm":40,"garmentLengthCm":88},{"sizeLabel":"XL","chestBustCm":108,"shoulderWidthCm":41,"garmentLengthCm":89}]'::jsonb, 'https://images.unsplash.com/photo-1790440966381-cc89370feb72?auto=format&fit=crop&w=720&h=900&q=80#art:tunic:embroidery', 'Katun toyobo', false, 466, 190, array['kantor', 'kondangan']::text[], '2026-11-09T09:00:00.000Z'),
('p12', 's_lawas', 'Blazer Wol Vintage Camel', 'Blazer wol 1990-an, label Jepang. Bahu berstruktur, satu noda kecil di lapisan dalam (sudah difoto).', 'outerwear', 'old_money', 'Coklat', array['#B88B5A', '#8C6A44']::text[], 215000, 1800000, 'very_good', true, 1, true, '[{"sizeLabel":"M (flat-lay)","chestBustCm":98,"shoulderWidthCm":42,"garmentLengthCm":70}]'::jsonb, 'https://images.unsplash.com/photo-1604914509286-abc02036617c?auto=format&fit=crop&w=720&h=900&q=80#art:blazer:plain', 'Wol 80%, nilon 20%', false, 2104, 960, array['kantor', 'old money']::text[], '2026-11-19T09:00:00.000Z'),
('p13', 's_lawas', 'Rok Plisket Vintage Hijau Botol', 'Rok plisket midi era 80-an dengan pinggang karet. Plisket masih tegas.', 'pants', 'old_money', 'Hijau', array['#244C3A', '#183427']::text[], 98000, 450000, 'like_new', true, 1, true, '[{"sizeLabel":"All size (flat-lay)","waistCm":64,"hipsCm":104,"garmentLengthCm":78}]'::jsonb, 'https://images.unsplash.com/photo-1756483500042-12c4444fc2f4?auto=format&fit=crop&w=720&h=900&q=80#art:skirt:pleat', 'Poliester', true, 870, 344, array['kuliah', 'weekend']::text[], '2026-11-17T09:00:00.000Z'),
('p14', 's_lawas', 'Kemeja Oxford Stripe Preloved', 'Oxford katun garis biru muda. Kerah button down, kondisi sangat baik tanpa cacat.', 'top', 'old_money', 'Biru', array['#BFD0E0', '#FFFFFF']::text[], 85000, 650000, 'very_good', true, 1, true, '[{"sizeLabel":"L (flat-lay)","chestBustCm":108,"shoulderWidthCm":46,"garmentLengthCm":76}]'::jsonb, 'https://images.unsplash.com/photo-1791391280267-a83f5649e762?auto=format&fit=crop&w=720&h=900&q=80#art:shirt:stripe', 'Katun oxford', false, 540, 210, array['kantor', 'kuliah']::text[], '2026-11-12T09:00:00.000Z'),
